  const game=room.game!; const isSpectator=room.isSpectator===true; const localSeatId=isSpectator?(room.players[0]?.seatId??""):room.viewerSeatId; const own=game.playerStates[localSeatId]; const me=room.players.find((p)=>p.seatId===localSeatId)??room.players[0];const viewerEliminated=!isSpectator&&own.eliminated===true;
  const [hovered,setHoveredCard]=useState<CardData|null>(null); const [hoveredStatuses,setHoveredStatuses]=useState<CardStatus[]>([]); const [zoneBrowser,setZoneBrowser]=useState<ZoneBrowser>(null); const [libraryTool,setLibraryTool]=useState<LibraryTool>(null); const [tokenModal,setTokenModal]=useState(false); const [counterSeat,setCounterSeat]=useState<string|null>(null); const [boardView,setBoardView]=useState<string>(isSpectator?"overview":room.viewerSeatId); const [menu,setMenu]=useState<{x:number;y:number;item:CardInstance;own:boolean;from:"battlefield"|"hand"|"stack"}|null>(null); const [attachPrompt,setAttachPrompt]=useState<AttachPrompt|null>(null); const [logOpen,setLogOpen]=useState(false); const [libraryMenu,setLibraryMenu]=useState(false); const [finishConfirmOpen,setFinishConfirmOpen]=useState(false);const [winnerSelectOpen,setWinnerSelectOpen]=useState(false);
  const setHovered=useCallback((card:CardData|null,statuses:CardStatus[]=[])=>{setHoveredCard(card);setHoveredStatuses(card?statuses:[]);},[]);
  const openStack=()=>{stackOpener.current=document.activeElement as HTMLElement;setHovered(null);setStackBrowserOpen(true);};
  const closeStack=()=>{setStackBrowserOpen(false);requestAnimationFrame(()=>stackOpener.current?.focus());};
  const [combatMode,setCombatMode]=useState<"idle"|"targeting">("idle"); const [selectedAttackers,setSelectedAttackers]=useState<string[]>([]);
  const [selectedPermanentIds,setSelectedPermanentIds]=useState<string[]>([]); const controllablePermanentIds=useMemo(()=>new Set(isSpectator||viewerEliminated?[]:own.battlefield.filter((item)=>item.controllerSeatId===room.viewerSeatId).map((item)=>item.instanceId)),[isSpectator,viewerEliminated,own.battlefield,room.viewerSeatId]); const activeSelectedPermanentIds=useMemo(()=>selectedPermanentIds.filter((id)=>controllablePermanentIds.has(id)),[selectedPermanentIds,controllablePermanentIds]); const selectedPermanentSet=useMemo(()=>new Set(activeSelectedPermanentIds),[activeSelectedPermanentIds]);
  const battlefieldRef=useRef<HTMLElement>(null); const marqueeRef=useRef<MarqueeGesture|null>(null); const [marquee,setMarquee]=useState<MarqueeGesture|null>(null);
  const suggestionNames=[...new Set(me.deck.commander.tokenNames??[])].slice(0,30).join("\u0000");
  const knownDeckCards=1+(own.handCount??own.hand.length)+own.graveyard.length+own.exile.length+own.battlefield.filter((item)=>!item.token&&!item.copy).reduce((sum,item)=>sum+item.quantity,0)+game.stack.filter((item)=>item.kind==="card"&&item.card?.ownerSeatId===localSeatId).length;
  const inferredLibraryCount=Math.max(0,me.deck.cardCount-knownDeckCards);
  const libraryCount=own.libraryCount??(own.library.length||inferredLibraryCount); const choosingOpeningHand=!viewerEliminated&&own.openingHandKept===false;
  const viewerSeatNumber=Math.max(1,(me.seat??0)+1);
  const active=room.players.find((player)=>player.seatId===game.activePlayerId);
  const combat=game.combat??fallbackCombat(game.activePlayerId,game.phase==="Combat"); const isActivePlayer=!isSpectator&&!viewerEliminated&&game.activePlayerId===room.viewerSeatId;
  const focusedSeatId=boardView==="overview"?null:(game.playerStates[boardView]?boardView:localSeatId);const focusedState=focusedSeatId?game.playerStates[focusedSeatId]:null;const focusedPlayer=focusedSeatId?room.players.find((player)=>player.seatId===focusedSeatId):null;const viewingOwnBoard=!isSpectator&&!viewerEliminated&&focusedSeatId===room.viewerSeatId;
  const dockSeatId=boardView==="overview"?localSeatId:(focusedSeatId??localSeatId);const dockState=game.playerStates[dockSeatId]??own;const dockPlayer=room.players.find((player)=>player.seatId===dockSeatId)??me;const dockIsOwn=!isSpectator&&!viewerEliminated&&dockSeatId===room.viewerSeatId;const dockLibraryCount=dockIsOwn?libraryCount:deckCount(dockState);
  const seatedPlayers=useMemo(()=>[...room.players].sort((a,b)=>a.seat-b.seat),[room.players]);
  const boardSeatOrder=useMemo(()=>isSpectator?seatedPlayers.map((player)=>player.seatId):[room.viewerSeatId,...seatedPlayers.filter((player)=>player.seatId!==room.viewerSeatId).map((player)=>player.seatId)],[isSpectator,room.viewerSeatId,seatedPlayers]);
  const allBattlefield=useMemo(()=>Object.values(game.playerStates).flatMap((playerState)=>playerState.battlefield),[game.playerStates]);
  const battlefieldById=useMemo(()=>new Map(allBattlefield.map((item)=>[item.instanceId,item])),[allBattlefield]);
  const attackById=useMemo(()=>new Map(combat.attackers.map((assignment)=>[assignment.battlefieldObjectId,assignment])),[combat.attackers]);
  function attackTargetLabel(assignment:AttackerAssignment){if(assignment.defenderType==="permanent"&&assignment.defendingPermanentId)return shortCombatName(battlefieldById.get(assignment.defendingPermanentId)?.card.name??"Permanent",16).toUpperCase();const defender=(room.players.find((player)=>player.seatId===assignment.defendingPlayerId)?.displayName??"Player").toUpperCase();return assignment.defendingPlayerId===room.viewerSeatId?`${defender} — YOU`:defender;}
  const selectedCreatureIds=useMemo(()=>activeSelectedPermanentIds.filter((id)=>{const item=own.battlefield.find((card)=>card.instanceId===id);return !!item&&item.controllerSeatId===room.viewerSeatId&&activeCardData(item).typeLine.toLowerCase().includes("creature");}),[activeSelectedPermanentIds,own.battlefield,room.viewerSeatId]);
  function beginAttackTargeting(){if(!isActivePlayer||!selectedCreatureIds.length)return;if(boardView!=="overview")setBoardView(room.viewerSeatId);setSelectedAttackers(selectedCreatureIds);setCombatMode("targeting");}
