    const boardIndex=Number(key)-1;if(Number.isInteger(boardIndex)&&boardIndex>=0&&boardIndex<boardSeatOrder.length){event.preventDefault();setBoardView(boardSeatOrder[boardIndex]);setSelectedPermanentIds([]);return;}
