    const cardNodes=topLevel.map((host)=>{const attachments=attachedByHost.get(host.instanceId)??[];if(!attachments.length)return renderCard(host);const step=overview?OVERVIEW_ATTACHMENT_STEP:ATTACHMENT_STEP;const groupStyle={"--attachment-span":`${attachments.length*step.x}px`,"--attachment-count":attachments.length} as React.CSSProperties;return <div className={`attachment-group ${overview?"overview-attachment-group":""}`} style={groupStyle} data-host-id={host.instanceId} data-attachment-count={attachments.length} key={host.instanceId}>{renderCard(host,"attachment-host",undefined,attachments.length)}{attachments.map((item,index)=>renderCard(item,"attachment-member",{"--attachment-offset-x":`${(index+1)*step.x}px`,"--attachment-offset-y":`${(index+1)*step.y}px`,"--attachment-index":index} as React.CSSProperties))}</div>;});
    const attachmentCounts=topLevel.map((host)=>(attachedByHost.get(host.instanceId)??[]).length);
